```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N;
    double D;
    if (scanf("%d %lf", &N, &D) != 2) return 0;

    double *P = (double *)malloc(N * sizeof(double));
    double *C = (double *)malloc(N * sizeof(double));
    for (int i = 0; i < N; i++) {
        scanf("%lf %lf", &P[i], &C[i]);
    }

    double *dp = (double *)malloc(N * sizeof(double));
    for (int i = 0; i < N; i++) {
        dp[i] = 1e100;
    }
    dp[0] = 0.0;

    for (int i = 0; i < N; i++) {
        if (dp[i] >= 1e99) continue;
        for (int j = i + 1; j < N; j++) {
            double dist = P[j] - P[i];
            double t = dist * dist / C[i];
            if (dp[i] + t < dp[j]) {
                dp[j] = dp[i] + t;
            }
        }
    }

    double ans = 1e100;
    for (int i = 0; i < N; i++) {
        double dist = D - P[i];
        double t = dist * dist / C[i];
        if (dp[i] + t < ans) {
            ans = dp[i] + t;
        }
    }

    printf("%.3f\n", ans);

    free(P);
    free(C);
    free(dp);
    return 0;
}
```

